+// loadExperimentRolloutState reads lifecycle state in the allocation snapshot.
+// Missing or deleted experiments retain logging. Only a known completed standard
+// experiment becomes ordinary winner delivery. Generated holdouts log separately.
+func loadExperimentRolloutState(tx *gorm.DB, orgID int64, flags []*model.FeatureFlag) error {
+	allocationsByExperiment := make(map[string][]*model.Allocation)
+	var experimentIDs []string
+	for _, flag := range flags {
+		if flag.CurrentEnvironment == nil {
+			continue
+		}
